package com.bookeat;
import com.bookeat.commerce.service.GeoRules;
import com.bookeat.reservation.service.BookingRules;
import com.bookeat.reservation.enums.*;
import com.bookeat.order.service.*;
import com.bookeat.order.enums.*;
import com.bookeat.diniticket.service.TicketRules;
import com.bookeat.diniticket.enums.TicketStatus;
import java.time.*;
import java.math.*;
import java.util.*;
/** Executable checks of real dependency-free production classes; no framework substitutes. */
public final class CommerceRuleChecks {
    static int count;
    static void check(boolean value,String message){count++;if(!value)throw new AssertionError(message);}
    public static void reservationLifecycle(){var now=Instant.parse("2026-09-13T10:00:00Z");check(BookingRules.ownerTransition(ReservationStatus.PENDING,ReservationStatus.CONFIRMED),"pending confirmation");check(!BookingRules.ownerTransition(ReservationStatus.CANCELLED,ReservationStatus.CONFIRMED),"cannot revive cancellation");check(!BookingRules.ownerTransition(ReservationStatus.CONFIRMED,ReservationStatus.REJECTED),"confirmed rejection blocked");check(BookingRules.cancellable(ReservationStatus.CONFIRMED,true,now.plusSeconds(1),now),"before cancellation deadline");check(!BookingRules.cancellable(ReservationStatus.CONFIRMED,true,now,now),"deadline exclusive");check(!BookingRules.cancellable(ReservationStatus.CONFIRMED,false,now.plusSeconds(1),now),"disabled cancellation");for(var s:List.of(ReservationStatus.DINING,ReservationStatus.COMPLETED,ReservationStatus.REJECTED,ReservationStatus.NO_SHOW))check(!BookingRules.cancellable(s,true,now.plusSeconds(3600),now),"terminal/started cancellation denied");}
    public static void recurrence(){var first=OffsetDateTime.parse("2026-01-31T12:00:00Z");var months=BookingRules.occurrences(first,ZoneOffset.UTC,RecurrenceType.MONTHLY,3,1);check(months.get(1).getDayOfMonth()==28,"month end clamp");check(months.get(2).getDayOfMonth()==31,"anchor preserved after February");var zone=ZoneId.of("America/New_York");var weekly=BookingRules.occurrences(OffsetDateTime.parse("2026-03-01T12:00:00-05:00"),zone,RecurrenceType.WEEKLY,3,1);check(weekly.get(1).getHour()==12&&weekly.get(1).getOffset().equals(ZoneOffset.of("-04:00")),"recurrence retains local wall time across DST");check(BookingRules.occurrences(first,ZoneOffset.UTC,RecurrenceType.NONE,1,1).size()==1,"one-off");boolean failed=false;try{BookingRules.occurrences(first,ZoneOffset.UTC,RecurrenceType.NONE,2,1);}catch(IllegalArgumentException e){failed=true;}check(failed,"NONE must be one occurrence");failed=false;try{BookingRules.occurrences(first,ZoneOffset.UTC,RecurrenceType.DAILY,13,1);}catch(IllegalArgumentException e){failed=true;}check(failed,"bounded recurrence");}
    public static void totalsAndSplits(){var t=OrderPricing.totals(new BigDecimal("200.00"),new BigDecimal("160.00"),new BigDecimal("5.00"));check(t.discount().equals(new BigDecimal("40.00")),"discount snapshot");check(t.tax().equals(new BigDecimal("8.00"))&&t.total().equals(new BigDecimal("168.00")),"tax on discounted net");check(OrderPricing.totals(new BigDecimal("0.10"),new BigDecimal("0.10"),new BigDecimal("5")).tax().equals(new BigDecimal("0.01")),"HALF_UP cent rounding");
        var random=new Random(58917);for(int i=0;i<1000;i++){int members=1+random.nextInt(50);var total=BigDecimal.valueOf(random.nextLong(1000000000L),2);var shares=OrderRules.splitEqual(total,members);check(shares.size()==members,"one share per member");check(shares.stream().reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(total)==0,"split sum exact");check(shares.stream().allMatch(s->s.scale()==2&&s.signum()>=0),"nonnegative cents");check(shares.get(0).subtract(shares.get(shares.size()-1)).compareTo(new BigDecimal("0.01"))<=0,"shares differ by at most one cent");}
        var huge=new BigDecimal("999999999999999999999999.99");check(OrderRules.splitEqual(huge,7).stream().reduce(BigDecimal.ZERO,BigDecimal::add).equals(huge),"no long overflow for combined order split");}
    public static void orderLifecycle(){check(OrderRules.transition(FoodOrderStatus.PLACED,FoodOrderStatus.ACCEPTED,false),"accept placed");check(!OrderRules.transition(FoodOrderStatus.ACCEPTED,FoodOrderStatus.CANCELLED,false),"customer cannot cancel kitchen acceptance");check(OrderRules.transition(FoodOrderStatus.PREPARING,FoodOrderStatus.REJECTED,false),"owner can resolve failed kitchen work");check(!OrderRules.transition(FoodOrderStatus.READY,FoodOrderStatus.COMPLETED,false),"dine-in must be served first");check(OrderRules.transition(FoodOrderStatus.READY,FoodOrderStatus.COMPLETED,true),"pickup completion");check(!OrderRules.transition(FoodOrderStatus.READY,FoodOrderStatus.SERVED,true),"takeaway not dine-in");for(var from:List.of(FoodOrderStatus.COMPLETED,FoodOrderStatus.CANCELLED,FoodOrderStatus.REJECTED))for(var to:FoodOrderStatus.values())check(!OrderRules.transition(from,to,false),"terminal order immutable");}
    public static void ticketLifecycle(){check(TicketRules.transition(TicketStatus.WAITING,TicketStatus.CALLED),"call waiting");check(!TicketRules.transition(TicketStatus.WAITING,TicketStatus.SEATED),"cannot skip arrival");check(!TicketRules.transition(TicketStatus.SEATED,TicketStatus.CANCELLED),"cannot cancel seated");check(!TicketRules.transition(TicketStatus.ARRIVED,TicketStatus.EXPIRED),"arrival stops automatic expiry");check(TicketRules.transition(TicketStatus.SEATED,TicketStatus.COMPLETED),"complete seated");for(var from:List.of(TicketStatus.COMPLETED,TicketStatus.CANCELLED,TicketStatus.EXPIRED,TicketStatus.NO_SHOW))for(var to:TicketStatus.values())check(!TicketRules.transition(from,to),"terminal ticket immutable");check(TicketRules.estimatedWait(1,15)==0&&TicketRules.estimatedWait(4,15)==45,"server wait estimate");}
    public static void geolocation(){check(GeoRules.distanceKm(13,80,13,80)==0,"same point");double a=GeoRules.distanceKm(13,80,12,77),b=GeoRules.distanceKm(12,77,13,80);check(Math.abs(a-b)<1e-9,"distance symmetric");check(Double.isFinite(GeoRules.distanceKm(0,0,0,180)),"antipodal numeric bound");check(GeoRules.etaMinutes(30)==60&&GeoRules.etaMinutes(0)==1,"disclosed estimate rule");boolean rejected=false;try{GeoRules.etaMinutes(Double.NaN);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"reject invalid coordinate estimate");}
    public static void main(String[] args){reservationLifecycle();recurrence();totalsAndSplits();orderLifecycle();ticketLifecycle();geolocation();System.out.println("PASS: "+count+" executable Phase 5–8 rule assertions against production Java classes");}
}
